import{_ as l,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Days NYC 2023: Ceph Telemetry - Observability in Action","description":"","frontmatter":{"title":"Ceph Days NYC 2023: Ceph Telemetry - Observability in Action","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-18T00:00:00.000Z","tags":["Ceph","Telemetry","Observability","Distributed Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_Ceph_Telemetry_-_Observability_in_Action.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_Ceph_Telemetry_-_Observability_in_Action.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_Days_NYC_2023_-_Ceph_Telemetry_-_Observability_in_Action.md"};function o(s,e,_,h,n,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph Days NYC 2023会议重点介绍了Ceph项目的Telemetry模块，探讨了其在Ceph集群监控和性能优化中的应用。会议涵盖了Telemetry模块的动机、架构、成功案例以及如何部署个人Telemetry服务。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>Telemetry模块的动机和目标</strong>：</p><ul><li>通过收集匿名和非识别数据，了解Ceph集群的分布、版本、存储容量、驱动模型、崩溃情况和使用特性。</li><li>帮助开发者和用户更好地理解和改进Ceph。</li></ul></li><li><p><strong>Telemetry模块的架构和功能</strong>：</p><ul><li>内置于Ceph的拦截器默认上报给上游Ceph。</li><li>用户可通过CLI命令或仪表板选择加入，并预览Telemetry报告。</li><li>报告包括基本信息、崩溃信息、设备健康指标、识别信息和性能计数器等。</li></ul></li><li><p><strong>隐私保护措施</strong>：</p><ul><li>数据匿名化处理，不包含敏感或识别信息。</li><li>通过分离报告端点增强隐私保护。</li></ul></li><li><p><strong>成功案例和实际应用</strong>：</p><ul><li>开发团队能够通过Telemetry数据及时发现并修复新出现的bug。</li><li>用户可通过Telemetry数据验证自己的安装，并贡献驱动健康指标的开放数据集。</li></ul></li><li><p><strong>部署自己的Telemetry服务</strong>：</p><ul><li>需要设置Telemetry服务器和配置Telemetry模块。</li><li>提供详细的安装指南和配置选项。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>强调Telemetry模块的隐私保护措施。</li><li>确定Telemetry数据在开发和用户支持中的重要作用。</li><li>讨论未来可能的改进方向，如离线Telemetry能力和更公开的驱动健康报告。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>优化Telemetry模块的数据收集和报告机制。</li><li>探索和实施离线Telemetry能力。</li><li>研究并公开更多关于驱动健康和性能的统计数据。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li>如何区分和过滤硬件故障导致的崩溃。</li><li>设备健康指标的预测效率和改进方向。</li><li>性能通道的启用及其可能的性能开销。</li><li>集群报告的持续性和数据的有效性。</li><li>公开驱动模型可靠性和性能报告的可能性。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>Telemetry模块是Ceph项目中一个重要的组成部分，它不仅帮助开发者更好地理解用户的使用情况，还为用户提供了验证和改进自己安装的工具。未来将继续优化和扩展Telemetry的功能，以更好地服务于Ceph社区。</p>',13)])])}const u=l(r,[["render",o]]);export{d as __pageData,u as default};
